var policy = Policy
    .Handle<HttpRequestException>()
    .OrResult<string>(r => !r.IsSuccessStatusCode)
    .FallbackAsync(
        fallbackAction: async (cancellationToken) =>
        {
            // Return popular content as fallback
            return await GetPopularContentAsync();
        },
        onFallbackAsync: async (exception, cancellationToken) =>
        {
            // Log the fallback
            await logger.LogWarning(
                "Recommendation service failed, using fallback");
        });

var recommendations = await policy.ExecuteAsync(
    async () => await GetPersonalizedRecommendationsAsync(userId));
